 const MARKER_RE = /^review-yeti-bot:v(\d+)$/u;

+/**
+ * Resolve the marker version a publisher payload carries.
+ * Rejects an absent body, and rejects the retired `ct-review-bot:v` marker.
+ */
 export function resolveMarker(body) {
-  return null;
+  if (!body) {
+    throw new Error('marker unusable: the pull request body is empty');
+  }
+  const match = body.match(MARKER_RE);
+  if (!match) {
+    throw new Error('marker unusable: the pull request body is empty');
+  }
+  return Number(match[1]);
 }

